INSERT INTO patch_issue_intel (patch_id, vendor_notice_id, issue_type, affected_scope, description, severity, workaround, publish_time, reference_url) VALUES
('KB5058379', 'KB5058379', 'Install rollback', NULL, 'Devices that have certain Citrix components installed might be unable to complete installation of the January 2025 Windows security update. This issue was observed on devices with Citrix Session Recording Agent (SRA) version 2411. The 2411 version of this application was released in December 2024. Affected devices might initially download and apply the January 2025 Windows security update correctly, such as via the Windows Update page in Settings. However, when restarting the device to complete the update installation, an error message with text similar to “Something didn’t go as planned. No need to worry – undoing changes” appears. The device will then revert to the Windows updates previously present on the device. This issue likely affects a limited number of organizations as version 2411 of the SRA application is a new version. Home users are not expected to be affected by this issue.', 'High', 'The issue has been resolved in Citrix Session Recording Agent version 2503, released on April 28, 2025, and newer versions. For details, see the documentation provided by Citrix at " Microsoft''s January Security Update Fails/Reverts on a machine with 2411 Session Recording Agent ".', '2025-05-13 00:00:00', 'https://support.microsoft.com/help/5058379'),
('KB5058379', 'KB5058379', 'Display issue', NULL, 'There are reports of blurry or unclear CJK (Chinese, Japanese, Korean) text when displayed at 96 DPI (100% scaling) in Chromium-based browsers such as Microsoft Edge and Google Chrome. The March 2025 Preview Update introduced Noto fonts in collaboration with Google, for CJK languages as fallbacks to improve text rendering when websites or apps don’t specify appropriate fonts. The issue is due to limited pixel density at 96 DPI, which can reduce the clarity and alignment of CJK characters. Increasing the display scaling improves clarity by enhancing text rendering.', 'Low', 'Microsoft has shared its findings on the blurry text issue at 96 DPI, along with potential solutions with Google for further discussion. For additional support, users can report issues related to Noto CJK fonts through the official Google Noto Fonts GitHub repository .', '2025-05-13 00:00:00', 'https://support.microsoft.com/help/5058379'),
('KB5058405', 'KB5058405', 'Display issue', 'All users', 'Noto fonts issue: There are reports of blurry or unclear CJK (Chinese, Japanese, Korean) text when displayed at 96 DPI (100% scaling) in Chromium-based browsers such as Microsoft Edge and Google Chrome. The March 2025 Preview Update introduced Noto fonts in collaboration with Google, for CJK languages as fallbacks to improve text rendering when websites or apps don’t specify appropriate fonts. The issue is due to limited pixel density at 96 DPI, which can reduce the clarity and alignment of CJK characters. Increasing the display scaling improves clarity by enhancing text rendering.', 'Low', 'Microsoft has shared its findings on the blurry text issue at 96 DPI, along with potential solutions with Google for further discussion. For additional support, users can report issues related to Noto CJK fonts through the official Google Noto Fonts GitHub repository .', '2025-05-13 00:00:00', 'https://support.microsoft.com/help/5058405'),
('KB5058405', 'KB5058405', 'Install rollback', 'All users', 'Recovery error with error code 0xc0000098: While installing the May 2025 Windows security update, some devices might encounter the following recovery error: Your PC/device needs to be repaired. The operating system couldn''t be loaded because a required file is missing or contains errors. File: ACPI.sys Error code: 0xc0000098 This issue has been observed on a small number of physical devices, but primarily on devices running in virtual environments, including: Azure Virtual Machines Azure Virtual Desktop On-premises virtual machines hosted on Citrix or Hyper-V Home users of Windows using Home or Pro editions are unlikely to face this issue as virtual machines are mostly used in IT environments. The ACPI.sys file (Advanced Configuration and Power Interface) is a critical system driver responsible for managing hardware resources and power states. Note: There are also reports of this same error occurring with a different file name.', 'High', 'This issue is addressed in KB5062170 . If you have not yet deployed the May 2025 Windows security update ( KB5058405 ) and your IT environment includes devices running in a virtual desktop infrastructure—such as Azure Virtual Machines, Azure Virtual Desktop, and on-premises virtual machines hosted on Citrix or Hyper-V— it’s recommended to apply the out-of-band update ( KB5062170 ) instead. Steps to recover your device If you experienced this issue and are unable to start Windows, try the following steps to recover your device. After you''ve recovered your device, install the out-of-band update ( KB5062170 ) via the Microsoft Update Catalog . On Recovery-enabled devices: Access the Windows Recovery Environment. Restart Windows. On non-Recovery enabled devices: Mount the virtual hard disk (VHD) from a remote device. Mount the VHD on another virtual machine (VM) or device as a data disk and then return it back to the affected VM. Restart Windows in normal mode. This will revert Windows to the last successfully installed Windows update. For Azure customers who have already applied the update and are experiencing issues, see the self-help repair steps outlined in Repair a Windows VM usin', '2025-05-13 00:00:00', 'https://support.microsoft.com/help/5058405'),
('KB5058411', 'KB5058411', 'Display issue', 'All users', 'Noto fonts issue: There are reports of blurry or unclear CJK (Chinese, Japanese, Korean) text when displayed at 96 DPI (100% scaling) in Chromium-based browsers such as Microsoft Edge and Google Chrome. The March 2025 Preview Update introduced Noto fonts in collaboration with Google, for CJK languages as fallbacks to improve text rendering when websites or apps don’t specify appropriate fonts. The issue is due to limited pixel density at 96 DPI, which can reduce the clarity and alignment of CJK characters. Increasing the display scaling improves clarity by enhancing text rendering.', 'Low', 'Microsoft has shared its findings on the blurry text issue at 96 DPI, along with potential solutions with Google for further discussion. For additional support, users can report issues related to Noto CJK fonts through the official Google Noto Fonts GitHub repository .', '2025-05-13 00:00:00', 'https://support.microsoft.com/help/5058411'),
('KB5058411', 'KB5058411', 'Printing issue', ': Enterprise customers and IT admins', 'Print to PDF might not work: After installing KB5055627 , you might encounter issues with the Microsoft Print to PDF functionality. Specifically, the Microsoft Print to PDF printer might no longer appear under Settings > Bluetooth & devices > Printers & scanners . You might also notice that enabling the Printing-PrintToPDFServices-Feature returns error code 0x800f0922 , which prevents the installation of the Microsoft Print to PDF printer driver located in C:\\Windows\\System32\\DriverStore\\FileRepository . To address this, try enabling the Printing-PrintToPDFServices-Feature using one of the following options: Option 1: Press Windows + R , type optional features, and enable Microsoft Print to PDF in the Windows Features dialog. Option 2: Open PowerShell as Administrator and run the following commands: Disable-WindowsOptionalFeature -Online -FeatureName Printing-PrintToPDFServices-Features​​​​​​​ Enable-WindowsOptionalFeature -Online -FeatureName Printing-PrintToPDFServices-Features Note: The final command might encounter an error with code 0x800f0922 .', 'Medium', 'This issue is addressed in KB5060829 .', '2025-05-13 00:00:00', 'https://support.microsoft.com/help/5058411'),
('KB5058392', 'KB5058392', 'Install rollback', NULL, 'Devices that have certain Citrix components installed might be unable to complete installation of the January 2025 Windows security update. This issue was observed on devices with Citrix Session Recording Agent (SRA) version 2411. The 2411 version of this application was released in December 2024. Affected devices might initially download and apply the January 2025 Windows security update correctly, such as via the Windows Update page in Settings. However, when restarting the device to complete the update installation, an error message with text similar to “Something didn’t go as planned. No need to worry – undoing changes” appears. The device will then revert to the Windows updates previously present on the device. This issue likely affects a limited number of organizations as version 2411 of the SRA application is a new version. Home users are not expected to be affected by this issue.', 'High', 'The issue has been resolved in Citrix Session Recording Agent version 2503, released on April 28, 2025, and newer versions. For details, see the documentation provided by Citrix at " Microsoft''s January Security Update Fails/Reverts on a machine with 2411 Session Recording Agent ".', '2025-05-13 00:00:00', 'https://support.microsoft.com/help/5058392'),
('KB5058379', 'KB5058379', 'Install rollback', 'Organizations using Citrix Session Recording Agent 2411', 'Citrix Session Recording Agent causes update rollback: Devices with certain Citrix components installed, specifically Citrix Session Recording Agent version 2411, can fail to complete installation of the January 2025 Windows security update. After restart, the update can revert with a message similar to ''Something didn’t go as planned. No need to worry – undoing changes''.', 'High', 'Microsoft points to Citrix Session Recording Agent version 2503, released April 28, 2025, and newer versions as the resolution path.', '2025-05-13 00:00:00', 'https://support.microsoft.com/help/5058379'),
('KB5058379', 'KB5058379', 'Display issue', 'All users', 'Blurry CJK text with Noto fonts at 96 DPI: There are reports of blurry or unclear Chinese, Japanese, and Korean text when displayed at 96 DPI in Chromium-based browsers after the Noto fallback font change.', 'Low', 'Microsoft shared findings with Google and recommends reporting Noto CJK font issues through the Google Noto Fonts GitHub repository.', '2025-05-13 00:00:00', 'https://support.microsoft.com/help/5058379'),
('KB5058405', 'KB5058405', 'Boot failure', 'All users, mainly virtual environments', 'Recovery error 0xc0000098 involving ACPI.sys: While installing the May 2025 Windows security update, some devices, especially virtual machines in Azure, Citrix, or Hyper-V environments, can hit recovery error 0xc0000098 citing ACPI.sys and fail to boot normally.', 'High', 'Microsoft says the issue is addressed in out-of-band update KB5062170 and provides recovery steps through Windows Recovery Environment or VHD mounting.', '2025-05-13 00:00:00', 'https://support.microsoft.com/help/5058405'),
('KB5058411', 'KB5058411', 'Printing issue', 'Enterprise customers and IT admins', 'Microsoft Print to PDF might disappear or fail: After installing KB5055627, Microsoft Print to PDF can disappear from Printers & scanners, and enabling Printing-PrintToPDFServices-Feature can return error 0x800f0922.', 'Medium', 'Microsoft states this issue is addressed in KB5060829 and documents temporary feature re-enable steps.', '2025-05-13 00:00:00', 'https://support.microsoft.com/help/5058411'),
('KB5040442', 'KB5040442', 'Licensing issue', 'Enterprise users', 'Windows Pro to Enterprise upgrade failure: After installing this update or later updates, devices can have issues upgrading from Windows Pro to a valid Windows Enterprise subscription. OS upgrade operations may fail and LicenseAcquisition can show access denied error 0x80070005.', 'Medium', 'Microsoft states this issue is addressed in KB5040527.', '2024-07-09 00:00:00', 'https://support.microsoft.com/help/5040442'),
('KB5040442', 'KB5040442', 'API regression', 'Enterprise users', 'Windows Update Agent API script failures: After installing this update, scripts using the Windows Update Agent API can return empty IUpdate object properties and error 0x8002802B when methods are called.', 'Medium', 'Microsoft states this issue is addressed in KB5040527.', '2024-07-09 00:00:00', 'https://support.microsoft.com/help/5040442'),
('KB5040442', 'KB5040442', 'BitLocker recovery', 'All users', 'Unexpected BitLocker recovery screen after startup: After installing the July 9, 2024 Windows security update, some devices can show a BitLocker recovery screen at startup and require the recovery key from the Microsoft account to unlock the drive.', 'High', 'Microsoft states this issue is addressed in KB5041585.', '2024-07-09 00:00:00', 'https://support.microsoft.com/help/5040442'),
('KB5041585', 'KB5041585', 'Boot failure', 'All users', 'Linux dual-boot startup failure after SBAT update: After installing this security update, devices using Windows and Linux dual-boot can fail to boot Linux and show ''Verifying shim SBAT data failed: Security Policy Violation'' because the SBAT setting was applied when dual boot was not detected correctly.', 'High', 'Microsoft says the September 2024 Windows security update KB5043076 and later updates do not contain the settings that caused this issue.', '2024-08-13 00:00:00', 'https://support.microsoft.com/help/5041585'),
('KB5044285', 'KB5044285', 'Service failure', 'All users', 'Following installation of the October 2024 security update, some devices report that the OpenSSH service fails to start, preventing SSH connections. The service can fail with no detailed logging and manual intervention is required to run sshd.exe.', 'High', 'Microsoft states this issue is addressed in KB5052094.', '2024-10-08 00:00:00', 'https://support.microsoft.com/help/5044285'),
('KB5046633', 'KB5046633', 'Service failure', 'All users', 'Following installation of the October 2024 security update, some devices report that the OpenSSH service fails to start, preventing SSH connections. The service can fail with no detailed logging and manual intervention is required to run sshd.exe.', 'High', 'Microsoft states this issue is addressed in KB5052094.', '2024-11-12 00:00:00', 'https://support.microsoft.com/help/5046633'),
('KB5058392', 'KB5058392', 'Install rollback', 'Organizations using Citrix Session Recording Agent 2411', 'Citrix Session Recording Agent causes update rollback: Devices with certain Citrix components installed, specifically Citrix Session Recording Agent version 2411, can fail to complete installation of the Windows security update and revert changes after restart.', 'High', 'Microsoft points to Citrix Session Recording Agent version 2503, released April 28, 2025, and newer versions as the resolution path.', '2025-05-13 00:00:00', 'https://support.microsoft.com/help/5058392');
